@traces('REQ-105')
def test_rate_limiting_returns_429(api_client, auth_headers):
    """Confirm rate limiter blocks after 100 requests and returns 429."""
    for i in range(100):
        r = api_client.get('/api/v1/data', headers=auth_headers)
        assert r.status_code == 200
    overflow = api_client.get('/api/v1/data', headers=auth_headers)
    assert overflow.status_code == 429

